SELECT CASE WHEN country IN ('DE', 'TH') THEN 'tier_1' ELSE 'other' END AS country_group, CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating FROM suppliers GROUP BY CASE WHEN country IN ('DE', 'TH') THEN 'tier_1' ELSE 'other' END, CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END;
